import json, re, sys, unicodedata
sys.path.insert(0, '/user/user1/autorlbench-runs/20261125151109-84018-31fa/workspace/third_party/python')
from inspect_ai.scorer._common import match_str, normalize_number
TAG = "</think" + ">"
false_neg = []; false_pos = []
gts_seen = {}
for f in range(1,6):
    for line in open(f'outputs/grpo/rollouts/{f}.jsonl'):
        r = json.loads(line); out = r['output']; gt = r['gts']
        gts_seen.setdefault(gt, 0); gts_seen[gt]+=1
        if TAG not in out: continue
        ans = out.split(TAG)[-1]
        num = None
        if str(gt).strip().isnumeric():
            words = re.split(r"\s+", ans.strip()); words.reverse()
            num = next((w for w in words if w.replace(".","").isnumeric()), None)
        eq = False
        if num is not None:
            try: eq = normalize_number(num)==normalize_number(str(gt))
            except Exception: eq=False
        if r['score']==0.0 and eq: false_neg.append((f,gt,num,ans[-150:]))
        if r['score']==1.0 and not eq: false_pos.append((f,gt,num,ans[-150:]))
print("false negatives (correct final number but score 0):", len(false_neg))
for x in false_neg[:10]: print(x)
print("false positives (score 1 but final number differs):", len(false_pos))
for x in false_pos[:10]: print(x)
# weird gts
weird = [g for g in gts_seen if not str(g).strip().isdigit()]
print("non-integer gts:", len(weird), weird[:20])
zw = [g for g in gts_seen if any(unicodedata.category(ch) in ('Cf','Zl','Zp','Zs') and ch not in ' ' for ch in str(g))]
print("gts with zero-width/format chars:", zw[:10])
EOF

